from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

# Version/title.
s=s.replace('<title>3DLite v3.99.1 LiteTrace Fast Mode</title>', '<title>3DLite v3.99.2 LiteTrace Fast Telemetry</title>')
s=s.replace("window.ThreeDLiteVersion='3.99.1';", "window.ThreeDLiteVersion='3.99.2';")

old="""  function finishRenderJob(job, status, details={}){\n    if(!job) return null;\n    const now=performance.now();\n    const started=Number(job.startedAt)||now;\n    job.status=status||job.status||'complete';\n    job.finishedAt=now;\n    job.elapsedMs=Math.max(0, now-started);\n    Object.assign(job, details||{});\n    const active=RenderJobStore.active;\n    if(active&&active.id===job.id) RenderJobStore.active=null;\n    const idx=RenderJobStore.history.findIndex(item=>item.id===job.id);\n    if(idx>=0) RenderJobStore.history[idx]={...RenderJobStore.history[idx],...job};\n    else RenderJobStore.history.push({...job});\n    if(RenderJobStore.history.length>24) RenderJobStore.history.splice(0, RenderJobStore.history.length-24);\n    return job;\n  }\n"""
new="""  function finishRenderJob(job, status, details={}){\n    if(!job) return null;\n    const now=performance.now();\n    const started=Number(job.startedAt)||now;\n    job.status=status||job.status||'complete';\n    job.finishedAt=now;\n    job.elapsedMs=Math.max(0, now-started);\n    Object.assign(job, details||{});\n    const active=RenderJobStore.active;\n    if(active&&active.id===job.id) RenderJobStore.active=null;\n    const idx=RenderJobStore.history.findIndex(item=>item.id===job.id);\n    if(idx>=0) RenderJobStore.history[idx]={...RenderJobStore.history[idx],...job};\n    else RenderJobStore.history.push({...job});\n    if(RenderJobStore.history.length>24) RenderJobStore.history.splice(0, RenderJobStore.history.length-24);\n    try{\n      if(window.ThreeDLiteLiteTraceFastTelemetry3992&&typeof window.ThreeDLiteLiteTraceFastTelemetry3992.finishJob==='function'){\n        window.ThreeDLiteLiteTraceFastTelemetry3992.finishJob(job);\n      }\n    }catch(e){ console.warn('[3DLite LiteTrace Fast Telemetry] finishJob',e); }\n    return job;\n  }\n"""
if old not in s: raise SystemExit('finishRenderJob anchor missing')
s=s.replace(old,new,1)

anchor="""  window.__3DLiteLiteTraceFast3991=true;\n  window.ThreeDLiteLiteTraceFast3991=Object.freeze({\n    version:'3.99.1',\n    preset:LiteTraceFastPreset3991,\n    resolveSettings:resolveLiteTraceFastSettings3991,\n    getLastStats:()=>LiteTraceFastRuntime3991.lastStats?{...LiteTraceFastRuntime3991.lastStats}:null\n  });\n"""
if anchor not in s: raise SystemExit('LiteTrace Fast API anchor missing')
telemetry="""  window.__3DLiteLiteTraceFast3991=true;\n  window.ThreeDLiteLiteTraceFast3991=Object.freeze({\n    version:'3.99.1',\n    preset:LiteTraceFastPreset3991,\n    resolveSettings:resolveLiteTraceFastSettings3991,\n    getLastStats:()=>LiteTraceFastRuntime3991.lastStats?{...LiteTraceFastRuntime3991.lastStats}:null\n  });\n\n  const LiteTraceFastTelemetry3992={\n    version:'3.99.2',\n    schema:1,\n    history:[],\n    last:null,\n    finishJob(job){\n      if(!job) return null;\n      const fast=job.liteTraceFast&&typeof job.liteTraceFast==='object'?job.liteTraceFast:null;\n      if(!fast) return null;\n      const width=Math.max(1,Number(job.width)||1), height=Math.max(1,Number(job.height)||1);\n      const elapsedMs=Math.max(0,Number(job.elapsedMs)||0);\n      const completedPixels=Math.max(0,Number(job.completedPixels)||0);\n      const rayBudget=Math.max(0,Number(fast.rayBudget)||0);\n      const sampleBudget=Math.max(0,Number(fast.sampleBudget)||0);\n      const entry={\n        schema:1, version:'3.99.2', renderer:'litetrace', mode:'fast',\n        jobId:job.id||null, status:job.status||'unknown', width, height, elapsedMs, completedPixels,\n        megapixels:(width*height)/1000000,\n        pixelsPerMs:elapsedMs>0?completedPixels/elapsedMs:0,\n        raysPerMs:elapsedMs>0?rayBudget/elapsedMs:0,\n        samplesPerMs:elapsedMs>0?sampleBudget/elapsedMs:0,\n        spp:Math.max(1,Number(fast.spp)||1), maxDepth:Math.max(1,Number(fast.maxDepth)||1),\n        rayBudget, sampleBudget, hitCount:Math.max(0,Number(fast.hitCount)||0), missCount:Math.max(0,Number(fast.missCount)||0),\n        primaryRays:Math.max(0,Number(fast.primaryRays)||0), secondaryRays:Math.max(0,Number(fast.secondaryRays)||0),\n        shadowRays:Math.max(0,Number(fast.shadowRays)||0), reflectionRays:Math.max(0,Number(fast.reflectionRays)||0),\n        refractionRays:Math.max(0,Number(fast.refractionRays)||0), terminatedPaths:Math.max(0,Number(fast.terminatedPaths)||0),\n        reflectionCap:Math.max(0,Number(fast.reflectionCap)||0), shadowRayCap:Math.max(0,Number(fast.shadowRayCap)||0),\n        maxSecondaryRays:Math.max(0,Number(fast.maxSecondaryRays)||0), maxShadowRays:Math.max(0,Number(fast.maxShadowRays)||0),\n        denoiseStrength:Number(fast.denoiseStrength)||0, finishedAt:Number(job.finishedAt)||performance.now()\n      };\n      entry.hitRate=(entry.hitCount+entry.missCount)>0?entry.hitCount/(entry.hitCount+entry.missCount):0;\n      entry.secondaryShare=entry.rayBudget>0?entry.secondaryRays/entry.rayBudget:0;\n      entry.shadowShare=entry.rayBudget>0?entry.shadowRays/entry.rayBudget:0;\n      entry.reflectionShare=entry.rayBudget>0?entry.reflectionRays/entry.rayBudget:0;\n      entry.refractionShare=entry.rayBudget>0?entry.refractionRays/entry.rayBudget:0;\n      this.last=entry; this.history.push(entry);\n      if(this.history.length>24) this.history.splice(0,this.history.length-24);\n      try{\n        if(window.ThreeDLiteL3NAdaptiveRender3990&&typeof window.ThreeDLiteL3NAdaptiveRender3990.observe==='function'){\n          window.ThreeDLiteL3NAdaptiveRender3990.observe({\n            renderer:'litetrace-fast', renderTimeMs:elapsedMs, rays:rayBudget, samples:sampleBudget,\n            qualityGain:0, noise:0, efficiency:elapsedMs>0?completedPixels/elapsedMs:0,\n            metadata:{liteTraceFast:{...entry}}\n          });\n        }\n      }catch(e){ console.warn('[3DLite LiteTrace Fast Telemetry] adaptive observe',e); }\n      return {...entry};\n    },\n    getLast(){ return this.last?{...this.last}:null; },\n    getHistory(){ return this.history.map(x=>({...x})); },\n    reset(){ this.history.length=0; this.last=null; return true; }\n  };\n  window.__3DLiteLiteTraceFastTelemetry3992=true;\n  window.ThreeDLiteLiteTraceFastTelemetry3992=LiteTraceFastTelemetry3992;\n"""
s=s.replace(anchor,telemetry,1)

# Feed the active job with a final copy of the renderer counters before finishRenderJob consumes it.
old2="""      LiteTraceFastRuntime3991.lastStats=fastStats;\n      job.liteTraceFast=fastStats;\n      job.rayBudget=fastStats.rayBudget;\n      job.sampleBudget=fastStats.sampleBudget;\n"""
new2="""      LiteTraceFastRuntime3991.lastStats=fastStats;\n      job.liteTraceFast={...fastStats};\n      job.rayBudget=fastStats.rayBudget;\n      job.sampleBudget=fastStats.sampleBudget;\n"""
if old2 not in s: raise SystemExit('fastStats job anchor missing')
s=s.replace(old2,new2,1)

if "3.99.2" not in s: raise SystemExit('version patch failed')
if "ThreeDLiteLiteTraceFastTelemetry3992" not in s: raise SystemExit('telemetry API patch failed')
p.write_text(s,encoding='utf-8')
print('patched v3.99.2 LiteTrace Fast telemetry wiring')
